#!/usr/bin/env python3
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-05
"""Evidence for node-internal data flow ("state links": a subscription callback deposits, another callback of the same
node reads and publishes) from the fishwait24 probes. The stored FISH graph has these links only by a structural
rule (every non-publishing subscription callback of a node → every publishing callback of that node); this tool says
which of them the trace can back, and how.

  1  retention    fish_msg_retain / fish_msg_release: the callback kept a reference to its message; the last
                  reference is dropped inside callback X  → X consumed it (queue) or X is the next deposit (overwrite)
  2  pointer      rcl_publish(message) points into a message another callback retained → forwarded as is
  3  stamp        fish_msg_stamp: the leading stamp of a published message equals the stamp of a message taken earlier
                  by another callback of the same node — counted only for stamps that are NOT /clock tick values
                  (under simulated time now() repeats the tick, so a tick-valued stamp identifies no message)
  A  ids          fish_msg_ids: the same for the other Time / UUID fields (stamp↔id, id↔id)
  C  lock         fish_lock: two callbacks of one node lock the same application mutex (supporting evidence only)

usage: state_links.py <session> [--scope __main__] [--tasks fish_tasks.json] [--truth truth.tsv] [-o out.json] [--show N]
Needs the session ingested (ingest_pg) with model + gantt spans (scripts/post_run_pipeline.sh)."""
import argparse, bisect, collections, csv, json, os, sys
import numpy as np
import psycopg2
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from fish_window import steady_window

DSN = 'host=localhost port=5432 dbname=fish user=fish password=fish'
TAKE2START_NS = 5_000_000      # a dispatched take is followed by its callback window within this
MIN_ID = 10 ** 12              # Time / UUID values below this are "unset" (zero stamps, small durations)
INFRA = ('/clock', '/parameter_events', '/rosout')   # ROS infrastructure: every node takes them, rclcpp's TimeSource keeps the last
                                                     # /clock message; fishwait24 does not probe them, earlier traces are filtered here

def hx(s):
    try:
        return int(s, 16) if isinstance(s, str) and s.lower().startswith('0x') else int(s)
    except (TypeError, ValueError):
        return 0

def pct(a, b):
    return f"{100.0 * a / b:.0f}%" if b else '-'

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('session'); ap.add_argument('--scope', default='__main__')
    ap.add_argument('--tasks', default=None, help='fish_tasks.json of this session (structural state links of the steady window; default: the stored graph)')
    ap.add_argument('--truth', default=None, help='TSV with source-verified verdicts (notes/state_links_truth_2026-10-05.tsv)')
    ap.add_argument('-o', '--out', default=None); ap.add_argument('--show', type=int, default=40)
    a = ap.parse_args()
    sid, scope = a.session, a.scope
    conn = psycopg2.connect(DSN); cur = conn.cursor()
    W = steady_window(cur, sid, scope, warmup_s=None); t_ss, t_end = W['t_ss'], W['t_end']
    print(f"session {sid}: window [{W['how']}] {(t_end - t_ss) / 1e9:.1f} s")

    # ---------------------------------------------------------------- graph: callbacks, their node, their windows
    cur.execute("SELECT node_id, type, label, children, attrs, pid, full_name, etype, ptype, cb_addr FROM graph_nodes "
                "WHERE session_id=%s AND scope=%s", (sid, scope))
    N = {}; parent = {}
    for nid, typ, label, children, attrs, pid, full, etype, ptype, cb in cur.fetchall():
        N[nid] = dict(id=nid, type=typ, label=label or '', attrs=attrs or {}, pid=pid, full=full, etype=etype, ptype=ptype, cb=cb)
        for ch in children or []:
            parent[ch] = nid
    def anc(f, typ):
        x = f
        while x in parent:
            x = parent[x]
            if N[x]['type'] == typ:
                return N[x]
        return None
    F = {i: n for i, n in N.items() if n['type'] == 'F'}
    for f in F.values():
        e, n, ex = anc(f['id'], 'E'), anc(f['id'], 'N'), anc(f['id'], 'EX')
        f['E'], f['N'] = e, n
        f['vpid'] = ex['pid'] if ex else f['attrs'].get('vpid')
        f['etype'] = (e or {}).get('etype') or f['ptype']
        f['node'] = (n or {}).get('full') or (n or {}).get('label') or '?'
        f['nh'] = ((n or {}).get('attrs') or {}).get('node_handle')
        f['ent'] = (e or {}).get('label') or f['label']
    cb2f = collections.defaultdict(list)
    for f in F.values():
        for c in [f['cb']] + list(f['attrs'].get('alt_cb_addrs') or []) + [f['attrs'].get('ipc_waitable')]:
            if c and c != 'NA' and f['vpid'] is not None:
                cb2f[(f['vpid'], c)].append((f['attrs'].get('init_ts_ns') or 0, f['attrs'].get('fini_ts_ns') or 2**62, f['id']))
    def cb_owner(pid, cb, ts):
        lst = cb2f.get((pid, cb))
        if not lst:
            return -1
        if len(lst) == 1:
            return lst[0][2]
        for a0, a1, f in lst:
            if a0 <= ts < a1:
                return f
        return min(lst, key=lambda x: abs(x[0] - ts))[2]
    cur.execute("SELECT pid, vtid, t0_ns, t1_ns, cb_addr FROM gantt_spans WHERE session_id=%s AND scope=%s ORDER BY pid, vtid, t0_ns", (sid, scope))
    TW = collections.defaultdict(lambda: ([], [], []))
    ninst = collections.Counter()
    for pid, vtid, t0, t1, cb in cur:
        f = cb_owner(pid, cb, t0)
        w = TW[(pid, vtid)]; w[0].append(t0); w[1].append(t1); w[2].append(f)
        if f >= 0 and t_ss <= t0 <= t_end:
            ninst[f] += 1
    def owner(pid, vtid, ts):
        """(F, window start) of the callback window on this thread that contains ts; (-1, 0) outside any window;
        F = -2 for a window whose callback the stored graph does not have (e.g. a second subscription on one
        (node, topic), which the model merges into one entity)."""
        w = TW.get((pid, vtid))
        if not w:
            return -1, 0
        i = bisect.bisect_right(w[0], ts) - 1
        unknown = None
        for j in range(i, max(-1, i - 8), -1):
            if w[0][j] <= ts <= w[1][j]:
                if w[2][j] >= 0:
                    return w[2][j], w[0][j]
                unknown = unknown or (-2, w[0][j])
        return unknown or (-1, 0)
    def prev_window(pid, vtid, ts):
        """(F, start) of the last window on this thread that ended before ts (the callback that just returned);
        F = -2 if the graph does not have that callback."""
        w = TW.get((pid, vtid))
        if not w:
            return -1, 0
        i = bisect.bisect_right(w[0], ts) - 1
        best = None
        for j in range(i, max(-1, i - 8), -1):
            if w[1][j] <= ts and (best is None or w[1][j] > best[2]):
                best = (w[2][j] if w[2][j] >= 0 else -2, w[0][j], w[1][j])
        return (best[0], best[1]) if best else (-1, 0)
    def next_window(pid, vtid, ts):
        w = TW.get((pid, vtid))
        if not w:
            return -1, 0
        i = bisect.bisect_left(w[0], ts)
        if i < len(w[0]) and w[0][i] - ts <= TAKE2START_NS and w[2][i] >= 0:
            return w[2][i], w[0][i]
        return -1, 0
    name = lambda f: (f"{F[f]['node'].split('/')[-1]}/{F[f]['etype']}:{str(F[f]['ent'])[-44:]}" if f in F
                      else {-1: 'outside any callback', -2: 'a callback the graph does not have'}.get(f, str(f)))
    subF = collections.defaultdict(list)          # (vpid, node_handle, topic) -> subscription callbacks of the graph
    for f in F.values():
        if f['etype'] == 'sub' and f['E']:
            subF[(f['vpid'], f['nh'], f['E']['label'])].append(f['id'])

    # ---------------------------------------------------------------- handles
    cur.execute("SELECT vpid, payload->>'subscription_handle', payload->>'rmw_subscription_handle', payload->>'topic_name', payload->>'node_handle' "
                "FROM ros2_trace WHERE session_id=%s AND event='ros2:rcl_subscription_init'", (sid,))
    sub_rcl = {}; sub_rmw = {}
    for v, sh, rh, t, nh in cur.fetchall():
        sub_rcl[(v, sh)] = (rh, t, nh); sub_rmw[(v, rh)] = (sh, t, nh)
    cur.execute("SELECT vpid, payload->>'publisher_handle', payload->>'rmw_publisher_handle', payload->>'topic_name', payload->>'node_handle' "
                "FROM ros2_trace WHERE session_id=%s AND event='ros2:rcl_publisher_init'", (sid,))
    pub_rcl = {}; pub_rmw = {}
    for v, ph, rh, t, nh in cur.fetchall():
        pub_rcl[(v, ph)] = (rh, t, nh); pub_rmw[(v, rh)] = (ph, t, nh)
    cur.execute("SELECT vpid, payload->>'handle', (payload->>'is_pub')::int, (payload->>'size')::bigint, (payload->>'stamp_off')::int, "
                "(payload->>'n_ids')::int, payload->>'type_name', payload->>'id_paths' FROM ros2_trace WHERE session_id=%s AND event='ros2:fish_msg_type'", (sid,))
    mtype = {}
    for v, h, ip, size, so, nid, tn, paths in cur.fetchall():
        mtype[(v, h, ip)] = dict(size=size or 0, stamp_off=-1 if so is None else so, n_ids=nid or 0, type=tn, paths=paths or '')
    cur.execute("SELECT event, count(*) FROM ros2_trace WHERE session_id=%s AND event IN ('ros2:fish_msg_retain','ros2:fish_msg_release',"
                "'ros2:fish_msg_type','ros2:fish_msg_stamp','ros2:fish_msg_ids','ros2:fish_lock','ros2:fish_lock_site') GROUP BY 1 ORDER BY 1", (sid,))
    counts = dict(cur.fetchall())
    print("probe events: " + (', '.join(f"{k.split(':')[1]} {v:,}" for k, v in counts.items()) or 'none — session traced without the fishwait24 events'))
    if mtype:
        ts_ = [m for (v, h, ip), m in mtype.items()]
        print(f"message types: {len(ts_)} publishers/subscriptions, {sum(1 for m in ts_ if m['stamp_off'] >= 0)} with a leading stamp, "
              f"{sum(1 for m in ts_ if m['n_ids'] > 0)} with further Time/UUID fields "
              f"({len({m['type'] for m in ts_})} types, {len({m['type'] for m in ts_ if m['stamp_off'] >= 0})} stamped, {len({m['type'] for m in ts_ if m['n_ids'] > 0})} with ids)")

    # ---------------------------------------------------------------- 1: retention
    cur.execute("SELECT vpid, vtid, ts_ns, event, payload->>'subscription_handle', payload->>'message', (payload->>'refs')::int FROM ros2_trace "
                "WHERE session_id=%s AND event IN ('ros2:fish_msg_retain','ros2:fish_msg_release') ORDER BY ts_ns", (sid,))
    open_ = {}                                   # (vpid, message) -> record
    RET = []                                     # dict(vpid, addr, size, t0, t1, f_dep, sh, refs, rel_f, rel_same_inst)
    for vpid, vtid, ts, ev, sh, msg, refs in cur:
        key = (vpid, msg)
        if ev.endswith('retain'):
            fdep, w0 = prev_window(vpid, vtid, ts)
            rh, topic, nh = sub_rcl.get((vpid, sh)) or (None, '?', None)
            size = (mtype.get((vpid, rh, 0)) or {}).get('size') or 0
            if (vpid, sh) not in sub_rcl:
                # intra-process delivery (fork images): the handle is the waitable, not an rcl subscription; the
                # callback that just returned is the subscription callback itself
                if fdep in F and F[fdep]['etype'] == 'sub':
                    topic, nh = str(F[fdep]['ent']), F[fdep]['nh']
                else:
                    fdep = -2
            # the callback that just returned must be a subscription callback of this (node, topic); otherwise the
            # dispatch belongs to a subscription the graph does not have as its own callback (merged entity)
            elif fdep not in subF.get((vpid, nh, topic), ()):
                fdep = -2
            r = dict(vpid=vpid, addr=hx(msg), size=size, t0=ts, t1=None, f_dep=fdep, sh=sh, refs=refs, rel_f=None, w0=w0,
                     topic=topic, nh=nh)
            open_[key] = r; RET.append(r)
        else:
            r = open_.pop(key, None)
            if r is None:
                continue
            r['t1'] = ts
            fr, wr = owner(vpid, vtid, ts)
            r['rel_f'] = fr; r['rel_w0'] = wr
    dep = collections.defaultdict(lambda: dict(n_ret=0, refs=collections.Counter(), rel=collections.Counter(), life=[]))
    rel_pair = collections.Counter()             # (f_dep, f_rel) -> messages released inside f_rel
    n_infra_ret = sum(1 for r in RET if r['topic'] in INFRA)
    RET = [r for r in RET if r['topic'] not in INFRA]
    unmodelled = collections.Counter()           # (vpid, node_handle, topic) -> retained messages of a callback the graph lacks
    nh_node = {(f['vpid'], f['nh']): f['node'] for f in F.values() if f['nh']}
    for r in RET:
        if not (t_ss <= r['t0'] <= t_end):
            continue
        if r['f_dep'] < 0:
            unmodelled[(nh_node.get((r['vpid'], r['nh']), '?'), r['topic'])] += 1
            continue
        d = dep[r['f_dep']]; d['n_ret'] += 1; d['refs'][r['refs']] += 1
        if r['t1'] is None:
            d['rel']['held at end'] += 1
        else:
            d['life'].append(r['t1'] - r['t0'])
            k = 'self' if r['rel_f'] == r['f_dep'] else r['rel_f']
            d['rel'][k] += 1
            if r['rel_f'] >= 0 and r['rel_f'] != r['f_dep']:
                rel_pair[(r['f_dep'], r['rel_f'])] += 1
    print(f"\n[1] retention: {len(RET):,} retained messages in the session ({n_infra_ret:,} more on infrastructure topics ignored), {sum(d['n_ret'] for d in dep.values()):,} in the window, "
          f"by {len(dep)} subscription callback(s); released inside ANOTHER callback: {sum(rel_pair.values()):,} messages, {len(rel_pair)} (deposit, consumer) pair(s)")
    if unmodelled:
        print(f"    + {sum(unmodelled.values()):,} retained by subscription callbacks the graph does not have ({len(unmodelled)} (node, topic); second subscription on one topic): "
              + ', '.join(f"{n.split('/')[-1]}:{t.split('/')[-1]} {c}" for (n, t), c in unmodelled.most_common(8)))

    # ---------------------------------------------------------------- 2: pointer identity at publish
    by_vpid = collections.defaultdict(lambda: collections.defaultdict(list))   # vpid -> addr -> [record]
    for r in RET:
        by_vpid[r['vpid']][r['addr']].append(r)
    addr_sorted = {v: sorted(d) for v, d in by_vpid.items()}
    ptr_pair = collections.Counter(); ptr_exact = collections.Counter(); n_pub_checked = 0
    if RET:
        cur.execute("SELECT vpid, vtid, ts_ns, payload->>'publisher_handle', payload->>'message' FROM ros2_trace WHERE session_id=%s AND event='ros2:rcl_publish' "
                    "AND ts_ns BETWEEN %s AND %s", (sid, t_ss, t_end))
        for vpid, vtid, ts, ph, msg in cur:
            al = addr_sorted.get(vpid)
            if not al:
                continue
            n_pub_checked += 1
            m = hx(msg); j = bisect.bisect_right(al, m) - 1
            if j < 0:
                continue
            for r in by_vpid[vpid][al[j]]:
                if r['t0'] <= ts and (r['t1'] is None or ts <= r['t1']) and m < r['addr'] + max(r['size'], 1):
                    fp, _ = owner(vpid, vtid, ts)
                    topic = (pub_rcl.get((vpid, ph)) or (None, '?'))[1]
                    ptr_pair[(r['f_dep'], fp, topic)] += 1
                    if m == r['addr']:
                        ptr_exact[(r['f_dep'], fp, topic)] += 1
                    break
    print(f"[2] pointer identity: {n_pub_checked:,} publishes checked in processes with retained messages; {sum(ptr_pair.values()):,} publish a retained message "
          f"({len(ptr_pair)} (deposit, publisher, topic) triple(s))")

    # ---------------------------------------------------------------- 3 / A: stamp and id lineage inside a node
    def load_ids(ev):
        if ev == 'stamp':
            cur.execute("SELECT vpid, vtid, ts_ns, payload->>'handle', (payload->>'is_pub')::int, (payload->>'stamp')::bigint FROM ros2_trace "
                        "WHERE session_id=%s AND event='ros2:fish_msg_stamp' ORDER BY ts_ns", (sid,))
            for vpid, vtid, ts, h, ip, st in cur:
                yield vpid, vtid, ts, h, ip, [('s', st)]
        else:
            cur.execute("SELECT vpid, vtid, ts_ns, payload->>'handle', (payload->>'flags')::int, payload->>'v0', payload->>'v1', payload->>'v2', "
                        "payload->>'v3', payload->>'v4', payload->>'v5' FROM ros2_trace WHERE session_id=%s AND event='ros2:fish_msg_ids' ORDER BY ts_ns", (sid,))
            for vpid, vtid, ts, h, fl, *vs in cur:
                yield vpid, vtid, ts, h, fl & 1, [('i', int(v)) for v in vs[:fl >> 1]]
    IN = collections.defaultdict(lambda: collections.defaultdict(list))    # (vpid, node_handle) -> value -> [(ts, f_in, topic, kind, polled)]
    OUT = []                                                                # (vpid, nh, ts, f_out, w0_out, topic, kind, value)
    n_in = collections.Counter(); n_out = collections.Counter()
    # Simulated time: now() returns the value of the last /clock message, so every message stamped with now() carries a
    # tick value and unrelated messages share it. A tick-valued stamp identifies the tick, not a message — only
    # non-tick stamps (measurement times that travel with the data) are evidence of lineage.
    ticks = set()
    for ev in ('stamp', 'ids'):
        for vpid, vtid, ts, h, ip, vals in load_ids(ev):
            if ip:
                _, topic, nh = pub_rmw.get((vpid, h)) or (None, None, None)
                if topic == '/clock':
                    ticks.update(v for _, v in vals)
                if not (t_ss <= ts <= t_end):
                    continue
                if topic is None or topic in INFRA:
                    continue
                fo, w0 = owner(vpid, vtid, ts)
                n_out[ev] += 1
                for kind, v in vals:
                    if v >= MIN_ID:
                        OUT.append((vpid, nh, ts, fo, w0, topic, kind, v))
            else:
                _, topic, nh = sub_rmw.get((vpid, h)) or (None, None, None)
                if topic == '/clock':
                    ticks.update(v for _, v in vals)
                if topic is None or topic in INFRA:
                    continue
                fi, w0 = owner(vpid, vtid, ts); polled = fi >= 0
                if fi < 0:
                    fi, w0 = next_window(vpid, vtid, ts)
                if fi in F and F[fi]['nh'] != nh:      # the window found belongs to another node (a take that was not
                    fi, w0 = -1, 0                     # dispatched, followed by somebody else's callback): unknown taker
                n_in[ev] += 1
                for kind, v in vals:
                    if v >= MIN_ID:
                        IN[(vpid, nh)][v].append((ts, fi, w0, topic, kind, polled))
    sim_time = any(t == '/clock' for (_, t, _) in sub_rcl.values())
    ticks_unknown = sim_time and not ticks      # traced without the /clock publisher stamps: no stamp match can be qualified
    lin = collections.defaultdict(lambda: collections.Counter())   # (f_in, topic_in, f_out, topic_out) -> Counter('ss','si','is','ii','tick')
    outs_of = collections.defaultdict(set)                         # (f_out, topic_out) -> set of (ts) outputs that carry any value
    for vpid, nh, ts, fo, w0o, topic, kind, v in OUT:
        outs_of[(fo, topic)].add(ts)
        seen = set()
        for tin, fi, w0i, tin_topic, kin, polled in IN.get((vpid, nh), {}).get(v, ()):
            if tin > ts or (fi, tin_topic) in seen:
                continue
            seen.add((fi, tin_topic))
            same_inst = (fi == fo and w0i == w0o)
            lin[(fi, tin_topic, fo, topic, same_inst)]['tick' if (v in ticks or ticks_unknown) else kin + kind] += 1
    # matched outputs per pair, by evidence class
    def pair_table(cross_only):
        rows = collections.defaultdict(lambda: dict(ss=0, other=0, tick=0))
        for (fi, ti, fo, to, same), c in lin.items():
            if cross_only and (same or fi == fo):
                continue
            k = (fi, ti, fo, to)
            rows[k]['ss'] += c.get('ss', 0); rows[k]['tick'] += c.get('tick', 0)
            rows[k]['other'] += sum(n for kk, n in c.items() if kk not in ('ss', 'tick'))
        return rows
    cross = pair_table(True)
    print(f"[3] leading stamp: {n_in['stamp']:,} taken + {n_out['stamp']:,} published messages carry one;  [A] further ids: {n_in['ids']:,} taken + {n_out['ids']:,} published")
    print(f"    simulated time: {'yes' if sim_time else 'no'}; /clock tick values known: {len(ticks):,}"
          + ("  — NONE: no stamp match of this session can be told from a coincidence of ticks" if ticks_unknown else ''))
    print(f"    matches inside a node, across callbacks (input taken by one callback, output published by another): {len(cross)} (in, out) pair(s); "
          f"{sum(1 for r in cross.values() if r['ss'])} on a non-tick stamp, {sum(1 for r in cross.values() if not r['ss'] and r['other'])} only through an id field (A), "
          f"{sum(1 for r in cross.values() if not r['ss'] and not r['other'] and r['tick'])} on tick values only")

    # ---------------------------------------------------------------- C: locks
    cur.execute("SELECT vpid, vtid, ts_ns, payload->>'callback', payload->>'mutex', payload->>'site', (payload->>'n')::bigint, (payload->>'hold_sum')::bigint, "
                "(payload->>'hold_max')::bigint, (payload->>'wait_max')::bigint, (payload->>'flags')::int FROM ros2_trace WHERE session_id=%s AND event='ros2:fish_lock' "
                "AND ts_ns BETWEEN %s AND %s", (sid, t_ss, t_end))
    LK = collections.defaultdict(lambda: collections.defaultdict(lambda: dict(inst=0, n=0, hold_sum=0, hold_max=0, wait_max=0, sites=set(), flags=0)))
    n_lock = 0
    for vpid, vtid, ts, cb, mx, site, n, hs, hm, wm, fl in cur:
        f = cb_owner(vpid, cb, ts)
        if f < 0:
            f, _ = owner(vpid, vtid, ts)
        d = LK[(vpid, mx)][f]; n_lock += 1
        d['inst'] += 1; d['n'] += n; d['hold_sum'] += hs; d['hold_max'] = max(d['hold_max'], hm); d['wait_max'] = max(d['wait_max'], wm); d['sites'].add(site); d['flags'] |= fl
    cur.execute("SELECT vpid, payload->>'site', payload->>'object', payload->>'symbol' FROM ros2_trace WHERE session_id=%s AND event='ros2:fish_lock_site'", (sid,))
    SITE = {(v, s): (os.path.basename(o or ''), sym or '') for v, s, o, sym in cur.fetchall()}
    lock_pair = collections.defaultdict(list)    # (f1, f2) -> [(mutex, vpid)]
    lock_cb = collections.defaultdict(set)
    for (vpid, mx), fs in LK.items():
        ff = sorted(f for f in fs if f >= 0)
        for f in ff:
            lock_cb[f].add(mx)
        for i in range(len(ff)):
            for j in range(len(ff)):
                if i != j:
                    lock_pair[(ff[i], ff[j])].append((mx, vpid))
    shared = [(k, fs) for k, fs in LK.items() if len([f for f in fs if f >= 0]) >= 2]
    same_node = sum(1 for k, fs in shared if len({F[f]['node'] for f in fs if f in F}) == 1)
    print(f"[C] locks: {n_lock:,} records in the window, {len(LK)} application mutex(es) locked by {len(lock_cb)} callback(s); "
          f"{len(shared)} mutex(es) locked by ≥2 callbacks ({same_node} of them inside one node)")

    # ---------------------------------------------------------------- the structural state links, with evidence
    links = []
    if a.tasks and os.path.exists(a.tasks):
        tj = json.load(open(a.tasks))
        for s in tj.get('sampled', []):
            if s.get('method') == 'state':
                links.append((s['writer_vertex'], s['reader_vertex'], s['topic'], s.get('n')))
    else:   # the stored graph: L3 comm edges of nature 'state' whose flow was inferred (not a polled take, not a tf lookup)
        cur.execute("SELECT source, target, attrs FROM graph_edges WHERE session_id=%s AND scope=%s AND level='L3' AND rel='comm' "
                    "AND attrs->>'nature'='state' AND attrs->>'flow_method'='state'", (sid, scope))
        for s_, t_, at in cur.fetchall():
            if s_ in F and t_ in F:
                links.append((s_, t_, at.get('topic') or '?', at.get('flow_n')))
    truth = collections.defaultdict(list)   # (node, deposit topic, reader etype, reader entity) -> rows (two timers of one period share a key)
    if a.truth and os.path.exists(a.truth):
        for row in csv.DictReader(open(a.truth), delimiter='\t'):
            truth[(row['node'], row['deposit_topic'], row['reader_etype'], row['reader_ent'])].append(row)
    pub_topics = collections.defaultdict(set)   # F -> data topics it publishes (tells two same-period timers apart)
    if truth:
        cur.execute("SELECT vpid, vtid, ts_ns, payload->>'publisher_handle' FROM ros2_trace WHERE session_id=%s AND event='ros2:rcl_publish' AND ts_ns BETWEEN %s AND %s",
                    (sid, t_ss, min(t_end, t_ss + 20_000_000_000)))
        for vpid, vtid, ts, ph in cur:
            fp, _ = owner(vpid, vtid, ts)
            if fp >= 0:
                pub_topics[fp].add((pub_rcl.get((vpid, ph)) or (None, '?'))[1])
    def truth_of(s, p, topic):
        if p not in F:
            return None
        rows = truth.get((F[p]['node'], topic, F[p]['etype'], str(F[p]['ent'])))
        if not rows:
            return None
        if len(rows) == 1:
            return rows[0]
        for row in rows:
            if row.get('reader_pub') and row['reader_pub'] in pub_topics.get(p, ()):
                return row
        return None
    out_rows = []
    if links:
        print(f"\nstructural state links of this session: {len(links)} in {len({F[p]['node'] for _, p, _, _ in links if p in F})} node(s)")
        hdr = f"{'node':28s} {'deposit (topic)':34s} {'reader':30s} {'ret%':>5s} {'rel→p':>6s} {'rel self':>8s} {'ptr':>5s} {'stamp':>9s} {'ids':>6s} {'tick':>5s} {'lock':>4s}  status"
        print(hdr)
        status_count = collections.Counter(); status_truth = collections.Counter()
        for s, p, topic, n in sorted(links, key=lambda x: (F[x[1]]['node'] if x[1] in F else '', x[2])):
            d = dep.get(s); n_dep = ninst.get(s, 0)
            n_ret = d['n_ret'] if d else 0
            rel_p = rel_pair.get((s, p), 0); rel_self = d['rel']['self'] if d else 0
            ptr = sum(c for (fd, fp, _), c in ptr_pair.items() if fd == s and fp == p)
            st_ss = st_other = st_tick = n_out_p = 0; always = False
            for (fi, ti, fo, to), r in cross.items():
                if fi == s and fo == p:
                    n_o = len(outs_of.get((fo, to), ()))
                    if max(r['ss'], r['other']) > max(st_ss, st_other) or (not (st_ss or st_other) and r['tick'] > st_tick):
                        st_ss, st_other, st_tick, n_out_p = r['ss'], r['other'], r['tick'], n_o
                    always = always or (n_o >= 20 and max(r['ss'], r['other']) >= 0.99 * n_o)
            lk = len(lock_pair.get((s, p), []))
            if rel_p:
                status = 'OBSERVED consumer (release in reader)'
            elif ptr:
                status = 'OBSERVED forward (pointer)'
            elif always:
                status = 'OBSERVED lineage (' + ('stamp' if st_ss else 'id') + ' always equal)'
            elif st_ss or st_other:
                status = 'partial match on a non-tick stamp'
            elif st_tick:
                status = 'tick-stamp match only (identifies the tick, not a message)'
            elif n_ret:
                status = 'deposit observed, reader assumed'
            elif lk:
                status = 'shared lock only'
            else:
                status = 'assumed'
            status_count[status.split(' (')[0]] += 1
            tr = truth_of(s, p, topic)
            if tr:
                status_truth[(status.split(' (')[0], tr.get('verdict', '?'), tr.get('pattern', '?'))] += 1
            node = F[p]['node'].split('/')[-1] if p in F else '?'
            print(f"{node[:28]:28s} {topic[-34:]:34s} {(F[p]['etype'] + ':' + str(F[p]['ent'])[-24:]) if p in F else '?':30s} "
                  f"{pct(n_ret, n_dep):>5s} {rel_p:6d} {rel_self:8d} {ptr:5d} {st_ss:5d}/{n_out_p:<4d}{st_other:5d} {st_tick:5d} {lk:4d}  {status}"
                  + (f"   | truth: {tr.get('verdict')} / {tr.get('pattern')}" if tr else ''))
            out_rows.append(dict(node=F[p]['node'] if p in F else None, deposit_topic=topic, writer=s, reader=p, reader_entity=str(F[p]['ent']) if p in F else None,
                                 deposit_instances=n_dep, retained=n_ret, released_in_reader=rel_p, released_in_self=rel_self, pointer_publishes=ptr,
                                 stamp_matches=st_ss, id_matches=st_other, tick_matches=st_tick, reader_outputs=n_out_p, shared_locks=lk, status=status,
                                 truth=(dict(verdict=tr.get('verdict'), pattern=tr.get('pattern'), flow=tr.get('flow')) if tr else None)))
        print("\nstatus of the structural links: " + ', '.join(f"{k}: {v}" for k, v in status_count.most_common()))
        if status_truth:
            print("against the source-verified verdicts (status | verdict | pattern → links):")
            for (st, vd, pt), c in sorted(status_truth.items(), key=lambda x: (-x[1], x[0])):
                print(f"   {c:3d}  {st:36s} {vd:8s} {pt}")

    # ---------------------------------------------------------------- what the probes show beyond the structural rule
    struct = {(s, p) for s, p, _, _ in links}
    print(f"\n[1] deposits: which callbacks keep their message, and where it is released (top {a.show})")
    for f, d in sorted(dep.items(), key=lambda x: -x[1]['n_ret'])[:a.show]:
        life = np.array(d['life']) / 1e6 if d['life'] else np.array([0.0])
        rel = ', '.join(f"{name(k) if isinstance(k, int) else k}: {c}" for k, c in d['rel'].most_common(3))
        print(f"   {name(f)[:74]:74s} retained {d['n_ret']:5d}/{ninst.get(f, 0):<5d} life p50 {np.median(life):8.1f} ms  released in → {rel}")
    extra_rel = [(k, c) for k, c in rel_pair.items() if k not in struct]
    print(f"\n[1] (deposit, consumer) pairs NOT among the structural links: {len(extra_rel)}")
    for (s, p), c in sorted(extra_rel, key=lambda x: -x[1])[:a.show]:
        same = F[s]['node'] == F[p]['node'] if s in F and p in F else False
        print(f"   {name(s)[:60]:60s} → {name(p)[:60]:60s} {c:6d} msgs  {'same node' if same else 'DIFFERENT node'}")
    print(f"\n[2] retained messages published as they are (top {a.show})")
    for (fd, fp, topic), c in sorted(ptr_pair.items(), key=lambda x: -x[1])[:a.show]:
        print(f"   {name(fd)[:56]:56s} → {name(fp)[:50]:50s} on {topic[-40:]:40s} {c:6d} (exact address {ptr_exact.get((fd, fp, topic), 0)}){'' if (fd, fp) in struct else '   [not a structural link]'}")
    print(f"\n[3/A] cross-callback lineage inside a node (top {a.show}; 'always' = every output of that topic matched on a non-tick value)")
    for (fi, ti, fo, to), r in sorted(cross.items(), key=lambda x: (-(x[1]['ss'] + x[1]['other']), -x[1]['tick']))[:a.show]:
        n_o = len(outs_of.get((fo, to), ()))
        m = max(r['ss'], r['other'])
        print(f"   {name(fi)[:52]:52s} → {name(fo)[:44]:44s} out {to[-36:]:36s} stamp {r['ss']:5d} id {r['other']:5d} tick {r['tick']:5d} of {n_o:5d} outputs"
              f"{'  always' if n_o >= 20 and m >= 0.99 * n_o else ''}{'' if (fi, fo) in struct else '   [not a structural link]'}")
    print(f"\n[C] application mutexes shared by callbacks of one node (top {a.show})")
    rows = []
    for (vpid, mx), fs in shared:
        ff = [f for f in fs if f in F]
        if len({F[f]['node'] for f in ff}) != 1:
            continue
        rows.append((sum(fs[f]['inst'] for f in ff), vpid, mx, ff, fs))
    for tot, vpid, mx, ff, fs in sorted(rows, key=lambda x: -x[0])[:a.show]:
        sites = sorted({SITE.get((vpid, s), ('', ''))[1][:60] or s for f in ff for s in fs[f]['sites']})
        print(f"   {F[ff[0]]['node'].split('/')[-1][:28]:28s} mutex {mx}: " + '; '.join(
            f"{F[f]['etype']}:{str(F[f]['ent'])[-22:]} ×{fs[f]['inst']} hold max {fs[f]['hold_max'] / 1e3:.1f} µs wait max {fs[f]['wait_max'] / 1e3:.1f} µs" for f in ff[:4])
            + (f"  [{' | '.join(sites[:2])}]" if sites else ''))
    if a.out:
        json.dump(dict(session=sid, counts=counts, links=out_rows,
                       deposits=[dict(f=f, name=name(f), retained=d['n_ret'], instances=ninst.get(f, 0),
                                      released_in={(name(k) if isinstance(k, int) else k): c for k, c in d['rel'].items()}) for f, d in dep.items()],
                       consumer_pairs=[dict(deposit=name(s), consumer=name(p), n=c, structural=(s, p) in struct) for (s, p), c in rel_pair.items()],
                       pointer=[dict(deposit=name(fd), publisher=name(fp), topic=t, n=c) for (fd, fp, t), c in ptr_pair.items()],
                       lineage=[dict(input=name(fi), in_topic=ti, output=name(fo), out_topic=to, stamp=r['ss'], id=r['other'], tick=r['tick'], outputs=len(outs_of.get((fo, to), ())),
                                     structural=(fi, fo) in struct) for (fi, ti, fo, to), r in cross.items()],
                       locks=dict(records=n_lock, mutexes=len(LK), callbacks=len(lock_cb), shared=len(shared), shared_same_node=same_node)),
                  open(a.out, 'w'), indent=1)
        print(f"\nwrote {a.out}")

if __name__ == '__main__':
    main()
